INSERT INTO races (id, label, size, speed, bonuses, bonus_desc, favored_class, traits, subraces, desc)
VALUES
  ('human', 'Humano', 'medium', 30, '{}'::jsonb, '+2 a cualquier atributo (a elegir)', 'any', '[{"name":"Bonificador de Atributo","description":"+2 a un atributo a elección del jugador."},{"name":"Talento Adicional","description":"Los humanos obtienen una dote adicional al nivel 1."},{"name":"Habilidades Adicionales","description":"Los humanos obtienen 1 punto de habilidad adicional por nivel."},{"name":"Idiomas","description":"Común. Bonus: cualquier idioma (excl. secretos)."}]'::jsonb, NULL, 'Versátiles y ambiciosos, los humanos dominan las Tierras Interiores. Su corta vida los impulsa a lograr grandes hazañas.'),
  ('elf', 'Elfo', 'medium', 30, '{"dexterity":2,"intelligence":2,"constitution":-2}'::jsonb, '+2 DES, +2 INT, −2 CON', 'wizard', '[{"name":"Visión en Penumbra","description":"Los elfos pueden ver el doble de lejos que los humanos en condiciones de poca luz."},{"name":"Inmunidades Élficas","description":"Inmunes a los efectos mágicos de sueño. +2 a TS contra encantamientos."},{"name":"Magia Élfica","description":"+2 a pruebas de Conocimiento arcano y para superar Resistencia a la Magia."},{"name":"Sentidos Agudos","description":"+2 a las pruebas de Percepción."},{"name":"Familiaridad con Armas","description":"Competencia con arco largo, arco largo compuesto, arco corto y arco corto compuesto."},{"name":"Idiomas","description":"Común y Élfico. Bonus: Célestial, Draconico, Gnoll, Gnomo, Orco, Silvano."}]'::jsonb, '[{"id":"elf-wood","label":"Elfo del Bosque","bonuses":{"dexterity":2,"wisdom":2,"intelligence":-2},"traits":[{"name":"Paso Silencioso","description":"+4 a pruebas de Sigilo en bosques."},{"name":"Conocimiento del Bosque","description":"Velocidad de movimiento no reducida por terreno de bosque."}]},{"id":"elf-high","label":"Elfo Alto","bonuses":{"dexterity":2,"intelligence":2,"constitution":-2},"traits":[{"name":"Hechizo de Elfo Alto","description":"Un hechizo de mago de nivel 0 adicional a voluntad."}]}]'::jsonb, 'Longevos y gráciles, los elfos son maestros de la magia y el arco. Su conexión con la naturaleza es profunda.'),
  ('dwarf', 'Enano', 'medium', 20, '{"constitution":2,"wisdom":2,"charisma":-2}'::jsonb, '+2 CON, +2 SAB, −2 CAR', 'fighter', '[{"name":"Visión en la Oscuridad","description":"Los enanos ven en la oscuridad total hasta 60 pies."},{"name":"Reconocimiento de Piedra","description":"+2 a pruebas de Percepción relacionadas con piedra o mampostería."},{"name":"Estabilidad","description":"+4 a su CMD contra derribo y maniobras de empuje."},{"name":"Avaricia","description":"+2 a pruebas de Tasación de metales y gemas."},{"name":"Odio","description":"+1 a tiradas de ataque contra orcos y goblinoides."},{"name":"Resistencia","description":"+2 a TS contra venenos, hechizos e ilusiones."},{"name":"Resistencia a la Magia","description":"+2 a TS contra hechizos y efectos similares."},{"name":"Familiaridad con Armas","description":"Competencia con hachas de batalla enanas y martillos de guerra enanos."},{"name":"Idiomas","description":"Común y Enano. Bonus: Gigante, Gnomo, Goblin, Orco, Terran, Subterráneo."}]'::jsonb, '[{"id":"dwarf-shield","label":"Enano de Escudo","bonuses":{"constitution":2,"wisdom":2,"charisma":-2},"traits":[{"name":"Defensa con Escudo","description":"+1 adicional a la CA cuando se usa escudo."}]},{"id":"dwarf-mountain","label":"Enano de Montaña","bonuses":{"constitution":2,"strength":2,"charisma":-2},"traits":[{"name":"Competencia con Armadura","description":"Competente con armadura media sin entrenamiento previo."}]}]'::jsonb, 'Tenaces y resistentes, los enanos son guardianes de las montañas y maestros de la forja.'),
  ('gnome', 'Gnomo', 'small', 20, '{"constitution":2,"charisma":2,"strength":-2}'::jsonb, '+2 CON, +2 CAR, −2 FUE', 'bard', '[{"name":"Visión en Penumbra","description":"Los gnomos ven el doble de lejos en condiciones de poca luz."},{"name":"Defensa contra Ilusiones","description":"+2 a TS contra ilusiones."},{"name":"Magia de Gnomo","description":"+1 al DC de ilusiones que lance. Si INT ≥ 10: dancing lights, ghost sound y prestidigitation a voluntad."},{"name":"Odio","description":"+1 a tiradas de ataque contra kobolds y goblinoides."},{"name":"Sentidos Agudos","description":"+2 a las pruebas de Percepción."},{"name":"Obsesión","description":"+2 a una prueba de Artesanía u Oficio elegida."},{"name":"Familiaridad con Armas","description":"Competencia con honda de bala, lanza corta de gnomo y gancho de hoces de gnomo."},{"name":"Idiomas","description":"Común, Gnomo y Silvano. Bonus: Dragón, Duende, Gigante, Goblin, Orco."}]'::jsonb, NULL, 'Curiosos e ingeniosos, los gnomos están conectados con el mundo feérico y poseen una magia innata de ilusión.'),
  ('halfling', 'Halfling', 'small', 20, '{"dexterity":2,"charisma":2,"strength":-2}'::jsonb, '+2 DES, +2 CAR, −2 FUE', 'rogue', '[{"name":"Sin Miedo","description":"+2 a TS contra miedo. Bonificador adicional de moral de +2 cuando es adyacente a un aliado."},{"name":"Suerte Halfling","description":"+1 a todas las tiradas de salvación."},{"name":"Pies Seguros","description":"+2 a pruebas de Acrobacias y Trepar."},{"name":"Sentidos Agudos","description":"+2 a las pruebas de Percepción."},{"name":"Familiaridad con Armas","description":"Competencia con tirachinas, lanza halfling y honda."},{"name":"Idiomas","description":"Común y Halfling. Bonus: Enano, Élfico, Gnomo, Goblin, Orco."}]'::jsonb, NULL, 'Pequeños y ágiles, los halflings poseen una suerte extraordinaria y una alegría de vivir contagiosa.'),
  ('half-elf', 'Medio Elfo', 'medium', 30, '{}'::jsonb, '+2 a cualquier atributo (a elegir)', 'any', '[{"name":"Visión en Penumbra","description":"Los medio elfos ven el doble de lejos en condiciones de poca luz."},{"name":"Adaptabilidad","description":"Habilidad de élite en una habilidad elegida al crear el personaje."},{"name":"Sangre Élfica","description":"Se considera élfico para todos los efectos mágicos y de dote."},{"name":"Inmunidades Élficas","description":"Inmune a hechizos de sueño. +2 a TS contra encantamientos."},{"name":"Sentidos Agudos","description":"+2 a las pruebas de Percepción."},{"name":"Multiclase","description":"Dos clases a elegir como clases favoritas en lugar de una."},{"name":"Idiomas","description":"Común y Élfico. Bonus: cualquier idioma (excl. secretos)."}]'::jsonb, NULL, 'Herederos de dos herencias, los medio elfos combinan lo mejor de ambos mundos con una versatilidad única.'),
  ('half-orc', 'Medio Orco', 'medium', 30, '{}'::jsonb, '+2 a un atributo (a elegir)', 'barbarian', '[{"name":"Visión en la Oscuridad","description":"Los medio orcos ven en la oscuridad total hasta 60 pies."},{"name":"Intimidador","description":"+2 a las pruebas de Intimidar."},{"name":"Ferocidad Orca","description":"Una vez por día, cuando sea reducido a 0 PV, permanece consciente con 1 PV durante 1 round."},{"name":"Sangre Orca","description":"Se considera orco para todos los efectos mágicos y de dote."},{"name":"Familiaridad con Armas","description":"Competencia con cimitarras orcos y hachas de mano."},{"name":"Idiomas","description":"Común y Orco. Bonus: Abisal, Draconico, Gigante, Goblin, Infernal."}]'::jsonb, '[{"id":"half-orc-tribal","label":"Medio Orco Tribal","bonuses":{"strength":2},"traits":[{"name":"Rugido de Guerra","description":"+1 a tiradas de ataque durante el primer round de combate."}]}]'::jsonb, 'Fuertes y resistentes, los medio orcos pertenecen a dos mundos y han aprendido a sobrevivir en ambos.'),
  ('aasimar', 'Aasimar', 'medium', 30, '{"wisdom":2,"charisma":2}'::jsonb, '+2 SAB, +2 CAR', 'paladin', '[{"name":"Visión en la Oscuridad","description":"Los aasimar ven en la oscuridad total hasta 60 pies."},{"name":"Habilidades de Aasimar","description":"+2 a Diplomacia y Percepción."},{"name":"Resistencia Celestial","description":"Resistencia al ácido 5, a la electricidad 5 y al fuego 5."},{"name":"Magia de Aasimar","description":"Puede lanzar daylight una vez al día como hechizo de clase."},{"name":"Lenguas Celestiales","description":"Habla Celestial además de Común."},{"name":"Idiomas","description":"Común y Celestial. Bonus: Dragón, Enano, Élfico, Gnomo, Halfling, Silvano."}]'::jsonb, NULL, 'Nacidos de herencia celestial, los aasimar poseen la gracia de los dioses y una resistencia innata al mal.'),
  ('tiefling', 'Tiefling', 'medium', 30, '{"dexterity":2,"intelligence":2,"charisma":-2}'::jsonb, '+2 DES, +2 INT, −2 CAR', 'rogue', '[{"name":"Visión en la Oscuridad","description":"Los tieflings ven en la oscuridad total hasta 60 pies."},{"name":"Habilidades de Tiefling","description":"+2 a Engaño e Intimidar."},{"name":"Resistencia Infernal","description":"Resistencia al frío 5, a la electricidad 5 y al fuego 5."},{"name":"Magia de Tiefling","description":"Puede lanzar darkness una vez al día como hechizo de clase."},{"name":"Sentidos Fiendish","description":"Puede detectar alineamientos buenos a voluntad."},{"name":"Idiomas","description":"Común y Abisal o Infernal. Bonus: Abisal, Dracónico, Enano, Élfico, Goblin, Halfling, Infernal, Orco."}]'::jsonb, NULL, 'Con herencia infernal en sus venas, los tieflings son criaturas de oscuridad y ambición, a menudo incomprendidos.'),
  ('tengu', 'Tengu', 'medium', 30, '{"dexterity":2,"wisdom":2,"constitution":-2}'::jsonb, '+2 DES, +2 SAB, −2 CON', 'rogue', '[{"name":"Visión en Penumbra","description":"Los tengu ven el doble de lejos que los humanos en condiciones de poca luz."},{"name":"Don de Lenguas","description":"+2 a Lingüística y aprenden un idioma adicional cada vez que suben de nivel."},{"name":"Pico","description":"Ataque natural de pico (1d3 daño)."},{"name":"Familiaridad con Armas","description":"Competencia con espadas (todas) y shurikens."},{"name":"Garras","description":"Dos ataques naturales de garra (1d3 daño cada uno)."},{"name":"Idiomas","description":"Común y Tengu. Bonus: Abisal, Élfico, Celestial, Gnoll, Sylvan y cualquier otro idioma."}]'::jsonb, NULL, 'Humanoides con forma de cuervo, los tengu son expertos espadachines y políglotas naturales.'),
  ('goblin', 'Goblin', 'small', 30, '{"dexterity":4,"strength":-2,"charisma":-2}'::jsonb, '+4 DES, −2 FUE, −2 CAR', 'rogue', '[{"name":"Visión en la Oscuridad","description":"Los goblins ven en la oscuridad total hasta 60 pies."},{"name":"Criatura Pequeña","description":"Como criaturas pequeñas ganan +1 a la CA, +1 a tiradas de ataque y +4 a Sigilo."},{"name":"Jinete de Bestias","description":"+4 a Montar y Manejo de Animales."},{"name":"Idiomas","description":"Goblin. Bonus: Común, Draconico, Enano, Gnoll, Orco, Infernal."}]'::jsonb, NULL, 'Pequeños, ágiles y traviesos, los goblins son criaturas caóticas conocidas por su piromanía y crueldad.'),
  ('hobgoblin', 'Hobgoblin', 'medium', 30, '{"dexterity":2,"constitution":2}'::jsonb, '+2 DES, +2 CON', 'fighter', '[{"name":"Visión en la Oscuridad","description":"Los hobgoblins ven en la oscuridad total hasta 60 pies."},{"name":"Entrenamiento Marcial","description":"+1 a tiradas de ataque con armas marciales."},{"name":"Idiomas","description":"Común y Goblin. Bonus: Dracónico, Enano, Gigante, Infernal, Orco."}]'::jsonb, NULL, 'Los hobgoblins son guerreros disciplinados y estrategas natos, la variante más civilizada y militarizada de los goblinoides.'),
  ('kobold', 'Kobold', 'small', 30, '{"dexterity":2,"strength":-4,"constitution":-2}'::jsonb, '+2 DES, −4 FUE, −2 CON', 'sorcerer', '[{"name":"Visión en la Oscuridad","description":"Los kobolds ven en la oscuridad total hasta 60 pies."},{"name":"Criatura Pequeña","description":"+1 CA, +1 a tiradas de ataque, +4 a Sigilo."},{"name":"Sensibilidad a la Luz","description":"Deslumbrados a plena luz del sol o en el área de un hechizo daylight."},{"name":"Sangre Dracónica","description":"+1 al DC de hechizos de encantamiento que lancen."},{"name":"Idiomas","description":"Dracónico. Bonus: Común, Gnomo, Goblin, Silvano, Terran, Subterráneo."}]'::jsonb, NULL, 'Pequeñas criaturas reptilianas que veneran a los dragones, los kobolds son expertos en trampas y minas.'),
  ('catfolk', 'Catfolk', 'medium', 30, '{"dexterity":2,"charisma":2,"wisdom":-2}'::jsonb, '+2 DES, +2 CAR, −2 SAB', 'ranger', '[{"name":"Visión en Penumbra","description":"Los catfolk ven el doble de lejos en condiciones de poca luz."},{"name":"Cazador Natural","description":"+2 a Percepción y Sigilo."},{"name":"Suerte Felina","description":"Una vez por día, puede relanzar una tirada de salvación de Reflejos fallida."},{"name":"Garras","description":"Dos ataques naturales de garra (1d4 daño cada uno) si no lleva armas."},{"name":"Idiomas","description":"Común y Catfolk. Bonus: Élfico, Gnoll, Gnomo, Goblin, Halfling, Orco, Silvano."}]'::jsonb, NULL, 'Humanoides felinos ágiles e impulsivos, los catfolk son cazadores naturales con un instinto salvaje.'),
  ('dhampir', 'Dhampir', 'medium', 30, '{"dexterity":2,"charisma":2,"constitution":-2}'::jsonb, '+2 DES, +2 CAR, −2 CON', 'rogue', '[{"name":"Visión en Penumbra","description":"Los dhampir ven el doble de lejos en condiciones de poca luz."},{"name":"Visión en la Oscuridad","description":"Los dhampir ven en la oscuridad total hasta 60 pies."},{"name":"Sensibilidad a la Luz","description":"Deslumbrados en plena luz solar."},{"name":"Detección de No Muertos","description":"Pueden detectar muertos vivientes a voluntad como el hechizo."},{"name":"Resistencia al Drenaje","description":"+2 a tiradas de salvación contra energía negativa y efectos de drenaje de nivel."},{"name":"Naturaleza No Muerta","description":"Inmune al efecto de sueño mágico y a parálisis."},{"name":"Idiomas","description":"Común. Bonus: Abisal, Árabe, Celestial, Dracónico, Élfico, Enano, Infernal."}]'::jsonb, NULL, 'Nacidos de la unión de vampiro y humano, los dhampir poseen poderes oscuros y una naturaleza ambivalente.'),
  ('orc', 'Orco', 'medium', 30, '{"strength":4,"intelligence":-2,"wisdom":-2,"charisma":-2}'::jsonb, '+4 FUE, −2 INT, −2 SAB, −2 CAR', 'barbarian', '[{"name":"Visión en la Oscuridad","description":"Los orcos ven en la oscuridad total hasta 60 pies."},{"name":"Sensibilidad a la Luz","description":"Deslumbrados en plena luz solar."},{"name":"Ferocidad","description":"Cuando son reducidos a 0 PV permanecen conscientes durante 1 round."},{"name":"Familiaridad con Armas","description":"Competencia con hachas de guerra y cimitarras."},{"name":"Idiomas","description":"Orco. Bonus: Común, Dracónico, Gigante, Gnoll, Goblin, Infernal."}]'::jsonb, NULL, 'Guerreros primitivos y feroces, los orcos son criaturas de violencia y fuerza bruta.'),
  ('drow', 'Drow', 'medium', 30, '{"dexterity":2,"charisma":2,"constitution":-2}'::jsonb, '+2 DES, +2 CAR, −2 CON', 'wizard', '[{"name":"Visión en la Oscuridad Superior","description":"Los drow ven en la oscuridad total hasta 120 pies."},{"name":"Ceguera por Luz","description":"Deslumbrados en plena luz solar; ciegos durante 1 round al entrar en la luz solar."},{"name":"Magia de Drow","description":"Puede lanzar dancing lights, darkness y faerie fire una vez al día cada una."},{"name":"Resistencia Mágica","description":"Resistencia a la magia 6 + nivel de personaje."},{"name":"Veneno de Drow","description":"+2 a tiradas de salvación contra venenos."},{"name":"Familiaridad con Armas","description":"Competencia con espada de mano, arco corto y arco corto compuesto."},{"name":"Idiomas","description":"Élfico y Subterráneo. Bonus: Abisal, Akvano, Celestial, Común, Draconico, Gnomo."}]'::jsonb, NULL, 'Elfos oscuros que viven en las profundidades subterráneas, los drow son criaturas de intriga y poder mágico.'),
  ('fetchling', 'Fetchling', 'medium', 30, '{"dexterity":2,"charisma":2,"wisdom":-2}'::jsonb, '+2 DES, +2 CAR, −2 SAB', 'rogue', '[{"name":"Visión en la Oscuridad","description":"Los fetchlings ven en la oscuridad total hasta 60 pies."},{"name":"Visión en Penumbra","description":"Los fetchlings ven el doble de lejos en poca luz."},{"name":"Resistencia de Sombra","description":"Resistencia a la energía fría 5 y a la electricidad 5."},{"name":"Magia de Fetchling","description":"Puede lanzar disguise self una vez al día."},{"name":"Forma Sombría","description":"+2 a pruebas de Sigilo; +4 en condiciones de poca luz."},{"name":"Idiomas","description":"Común. Bonus: Abisal, Akvano, Celestial, Draconico, Infernal, Terran."}]'::jsonb, NULL, 'Descendientes de humanos atrapados en el Plano de las Sombras, los fetchlings son seres de luz y oscuridad.'),
  ('ifrit', 'Ifrit', 'medium', 30, '{"dexterity":2,"charisma":2,"wisdom":-2}'::jsonb, '+2 DES, +2 CAR, −2 SAB', 'sorcerer', '[{"name":"Visión en la Oscuridad","description":"Los ifrits ven en la oscuridad total hasta 60 pies."},{"name":"Resistencia al Fuego","description":"Resistencia al fuego 5."},{"name":"Magia de Ifrit","description":"Puede lanzar burning hands una vez al día."},{"name":"Afinidad con el Fuego","description":"+1 al DC de hechizos del descriptor fuego."},{"name":"Idiomas","description":"Común e Ignan. Bonus: Akvano, Abisal, Célestial, Élfico, Gnomo, Terran."}]'::jsonb, NULL, 'Descendientes de genios del fuego (efreet), los ifrits son criaturas apasionadas con llamas en su sangre.'),
  ('oread', 'Oread', 'medium', 20, '{"strength":2,"wisdom":2,"charisma":-2}'::jsonb, '+2 FUE, +2 SAB, −2 CAR', 'monk', '[{"name":"Visión en la Oscuridad","description":"Los oreads ven en la oscuridad total hasta 60 pies."},{"name":"Resistencia al Ácido","description":"Resistencia al ácido 5."},{"name":"Magia de Oread","description":"Puede lanzar magic stone una vez al día."},{"name":"Naturaleza Pétrea","description":"+2 a pruebas de Estabilidad contra derribo y empuje."},{"name":"Idiomas","description":"Común y Terran. Bonus: Akvano, Célestial, Élfico, Gnomo, Ignan."}]'::jsonb, NULL, 'Descendientes de genios de tierra (shaitans), los oreads son seres estables y resilientes con piel pétrea.'),
  ('ratfolk', 'Ratfolk', 'small', 20, '{"dexterity":2,"intelligence":2,"strength":-2}'::jsonb, '+2 DES, +2 INT, −2 FUE', 'alchemist', '[{"name":"Visión en la Oscuridad","description":"Los ratfolk ven en la oscuridad total hasta 60 pies."},{"name":"Criatura Pequeña","description":"+1 CA, +1 a tiradas de ataque, +4 a Sigilo."},{"name":"Enjambre","description":"+2 a tiradas de ataque y Esquivar si hay otro ratfolk adyacente al mismo enemigo."},{"name":"Nariz Aguda","description":"+2 a Percepción basada en olfato."},{"name":"Ingenio Alquímico","description":"+2 a pruebas de Artesanía (alquimia)."},{"name":"Idiomas","description":"Común. Bonus: Akvano, Dracónico, Élfico, Enano, Gnoll, Gnomo, Goblin, Orco."}]'::jsonb, NULL, 'Humanoides roedores inteligentes y sociables, los ratfolk son mercaderes y alquimistas naturales.'),
  ('sylph', 'Sylph', 'medium', 30, '{"dexterity":2,"intelligence":2,"constitution":-2}'::jsonb, '+2 DES, +2 INT, −2 CON', 'wizard', '[{"name":"Visión en la Oscuridad","description":"Los sylphs ven en la oscuridad total hasta 60 pies."},{"name":"Resistencia a la Electricidad","description":"Resistencia a la electricidad 5."},{"name":"Magia de Sylph","description":"Puede lanzar feather fall una vez al día."},{"name":"Afinidad con el Aire","description":"+1 al DC de hechizos del descriptor electricidad."},{"name":"Idiomas","description":"Común y Auran. Bonus: Akvano, Célestial, Élfico, Ignan, Terran."}]'::jsonb, NULL, 'Descendientes de genios del aire (djinn), los sylphs son etéreos y curiosos, con el viento en su alma.'),
  ('undine', 'Undine', 'medium', 30, '{"dexterity":2,"wisdom":2,"strength":-2}'::jsonb, '+2 DES, +2 SAB, −2 FUE', 'druid', '[{"name":"Visión en la Oscuridad","description":"Los undines ven en la oscuridad total hasta 60 pies."},{"name":"Resistencia al Frío","description":"Resistencia al frío 5."},{"name":"Magia de Undine","description":"Puede lanzar hydraulic push una vez al día."},{"name":"Natación","description":"Velocidad de natación 30 pies. +8 a pruebas de Nadar."},{"name":"Idiomas","description":"Común y Akvano. Bonus: Abisal, Célestial, Élfico, Gnomo, Ignan, Terran."}]'::jsonb, NULL, 'Descendientes de genios del agua (marids), los undines son seres tranquilos con afinidad por el mar.'),
  ('kitsune', 'Kitsune', 'medium', 30, '{"dexterity":2,"charisma":2,"strength":-2}'::jsonb, '+2 DES, +2 CAR, −2 FUE', 'bard', '[{"name":"Visión en Penumbra","description":"Los kitsune ven el doble de lejos en condiciones de poca luz."},{"name":"Cambiaformas","description":"Pueden alternar entre forma humanoide y forma de zorro como acción estándar."},{"name":"Magia Zorruna","description":"Puede lanzar dancing lights tres veces al día."},{"name":"Ataque de Mordisco","description":"En forma de kitsune tiene un ataque de mordisco (1d4)."},{"name":"Idiomas","description":"Común y Zorro. Bonus: Célestial, Gnomo, Silvano."}]'::jsonb, NULL, 'Cambiaformas feéricos con forma de zorro, los kitsune son encantadores y perspicaces.'),
  ('nagaji', 'Nagaji', 'medium', 30, '{"strength":2,"charisma":2,"intelligence":-2}'::jsonb, '+2 FUE, +2 CAR, −2 INT', 'paladin', '[{"name":"Visión en Penumbra","description":"Los nagaji ven el doble de lejos en condiciones de poca luz."},{"name":"Resistencia Escamosa","description":"+2 a TS contra venenos, encantamientos e ilusiones mágicas."},{"name":"Mirada Hipnótica","description":"Una vez al día puede usar hipnosis sobre un ser en contacto visual (CD 10+mitad nivel+CAR)."},{"name":"Idiomas","description":"Común y Nagaji. Bonus: Abisal, Akvano, Célestial, Dracónico, Infernal."}]'::jsonb, NULL, 'Humanoides reptilianos creados por nagas divinas, los nagaji son sirvientes leales y temibles.'),
  ('samsaran', 'Samsaran', 'medium', 30, '{"intelligence":2,"wisdom":2,"constitution":-2}'::jsonb, '+2 INT, +2 SAB, −2 CON', 'cleric', '[{"name":"Visión en Penumbra","description":"Los samsarans ven el doble de lejos en condiciones de poca luz."},{"name":"Vidas Pasadas","description":"Puede usar dos habilidades de clase de una lista de clase diferente a la suya."},{"name":"Resistencia Mística","description":"+2 a TS contra hechizos de encantamiento."},{"name":"Idiomas","description":"Común y Samsaran. Bonus: cualquier idioma (excl. secretos)."}]'::jsonb, NULL, 'Seres que reencaran perpetuamente, los samsarans retienen vagos recuerdos de vidas pasadas.'),
  ('wayang', 'Wayang', 'small', 20, '{"dexterity":2,"intelligence":2,"wisdom":-2}'::jsonb, '+2 DES, +2 INT, −2 SAB', 'sorcerer', '[{"name":"Visión en la Oscuridad","description":"Los wayangs ven en la oscuridad total hasta 60 pies."},{"name":"Criatura Pequeña","description":"+1 CA, +1 a tiradas de ataque, +4 a Sigilo."},{"name":"Magia de Wayang","description":"Puede lanzar ghost sound, haunted fey aspect y pass without trace una vez al día cada uno."},{"name":"Idiomas","description":"Común y Wayang. Bonus: cualquier idioma."}]'::jsonb, NULL, 'Pequeños seres de sombra que escaparon del Plano de las Sombras, los wayangs son reservados y melancólicos.'),
  ('vanara', 'Vanara', 'medium', 30, '{"dexterity":2,"wisdom":2,"charisma":-2}'::jsonb, '+2 DES, +2 SAB, −2 CAR', 'monk', '[{"name":"Visión en Penumbra","description":"Los vanaras ven el doble de lejos en poca luz."},{"name":"Cola Prensil","description":"Tienen una cola que puede sostener objetos pero no armas."},{"name":"Trepar","description":"Velocidad de escalar 30 pies. +8 a pruebas de Trepar."},{"name":"Idiomas","description":"Común y Vanara. Bonus: Akvano, Célestial, Élfico, Silvano."}]'::jsonb, NULL, 'Humanoides simianos de las selvas tropicales, los vanaras son ágiles y espirituales.'),
